import sys
from array import array

sys.setrecursionlimit(1_000_000)

def solve():
    input = sys.stdin.buffer.readline
    N, M, Q = map(int, input().split())

    intervals = []
    for _ in range(M):
        s, t = map(int, input().split())
        if s < t:
            intervals.append((s, t, 0))  # valley
        else:
            intervals.append((t, s, 1))  # peak

    size = 1
    while size < N + 1:
        size <<= 1

    roots = [[0] * (size << 1), [0] * (size << 1)]

    key = array('I', [0])
    left = array('I', [0])
    right = array('I', [0])
    pri = array('I', [0])
    val = array('I', [0])
    mx = array('I', [0])

    rng = 2463534242

    def new_node(k, v):
        nonlocal rng
        rng ^= (rng << 13) & 0xffffffff
        rng ^= rng >> 17
        rng ^= (rng << 5) & 0xffffffff
        rng &= 0xffffffff
        key.append(k)
        left.append(0)
        right.append(0)
        pri.append(rng)
        val.append(v)
        mx.append(v)
        return len(key) - 1

    def pull(x):
        a = val[x]
        l = left[x]
        r = right[x]
        if l and mx[l] > a:
            a = mx[l]
        if r and mx[r] > a:
            a = mx[r]
        mx[x] = a

    def rotate_right(x):
        y = left[x]
        left[x] = right[y]
        right[y] = x
        pull(x)
        pull(y)
        return y

    def rotate_left(x):
        y = right[x]
        right[x] = left[y]
        left[y] = x
        pull(x)
        pull(y)
        return y

    def insert(root, k, v):
        if root == 0:
            return new_node(k, v)

        if k == key[root]:
            if v > val[root]:
                val[root] = v
                pull(root)
            return root

        if k < key[root]:
            left[root] = insert(left[root], k, v)
            if pri[left[root]] > pri[root]:
                root = rotate_right(root)
            else:
                pull(root)
        else:
            right[root] = insert(right[root], k, v)
            if pri[right[root]] > pri[root]:
                root = rotate_left(root)
            else:
                pull(root)
        return root

    def range_max(root, ql, qr, lo=1, hi=None):
        if root == 0 or ql > hi or qr < lo:
            return 0
        if ql <= lo and hi <= qr:
            return mx[root]

        k = key[root]
        ans = 0
        if ql <= k <= qr:
            ans = val[root]

        if lo < k:
            z = range_max(left[root], ql, qr, lo, k - 1)
            if z > ans:
                ans = z
        if k < hi:
            z = range_max(right[root], ql, qr, k + 1, hi)
            if z > ans:
                ans = z
        return ans

    def point_add(tp, x, y, idx):
        p = x + size
        rt = roots[tp]
        while p:
            rt[p] = insert(rt[p], y, idx)
            p >>= 1

    def rectangle_query(tp, xl, xr, yl, yr):
        if xl > xr or yl > yr:
            return 0

        ans = 0
        l = xl + size
        r = xr + size
        rt = roots[tp]

        while l <= r:
            if l & 1:
                z = range_max(rt[l], yl, yr, 1, N)
                if z > ans:
                    ans = z
                l += 1
            if not (r & 1):
                z = range_max(rt[r], yl, yr, 1, N)
                if z > ans:
                    ans = z
                r -= 1
            l >>= 1
            r >>= 1
        return ans

    latest_left = [0] * (N + 1)
    latest_right = [0] * (N + 1)
    bad = [0] * (M + 1)

    for i, (l, r, tp) in enumerate(intervals, 1):
        b = latest_left[l]
        if latest_right[r] > b:
            b = latest_right[r]

        # Previous interval: l' < l < r' < r
        z = rectangle_query(tp, 1, l - 1, l + 1, r - 1)
        if z > b:
            b = z

        # Previous interval: l < l' < r < r'
        z = rectangle_query(tp, l + 1, r - 1, r + 1, N)
        if z > b:
            b = z

        bad[i] = b

        point_add(tp, l, r, i)
        latest_left[l] = i
        latest_right[r] = i

    segsize = 1
    while segsize < M + 1:
        segsize <<= 1
    seg = [0] * (segsize << 1)
    for i in range(1, M + 1):
        seg[segsize + i] = bad[i]
    for i in range(segsize - 1, 0, -1):
        seg[i] = max(seg[i << 1], seg[i << 1 | 1])

    out = []
    for _ in range(Q):
        L, R = map(int, input().split())
        l = L + segsize
        r = R + segsize
        best = 0
        while l <= r:
            if l & 1:
                if seg[l] > best:
                    best = seg[l]
                l += 1
            if not (r & 1):
                if seg[r] > best:
                    best = seg[r]
                r -= 1
            l >>= 1
            r >>= 1
        out.append("Yes" if best < L else "No")

    print("\n".join(out))

if __name__ == "__main__":
    solve()

