def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    q = data[0]
    queries = data[1:]

    roots = [math.isqrt(a) for a in queries]
    limit = max(roots)

    omega = bytearray(limit + 1)
    for p in range(2, limit + 1):
        if omega[p] == 0:
            for x in range(p, limit + 1, p):
                omega[x] += 1

    best = [0] * (limit + 1)
    current = 0
    for x in range(2, limit + 1):
        if omega[x] == 2:
            current = x
        best[x] = current

    ans = [str(best[r] * best[r]) for r in roots]
    sys.stdout.write("\n".join(ans))

