import sys

def solve_case(n, k, cakes):
    L = 2 * k

    vals = []
    base = []
    for x, y, z in cakes:
        a = (x, y, z)
        b = 0
        if a[1] > a[b]:
            b = 1
        if a[2] > a[b]:
            b = 2
        vals.append(a)
        base.append(b)

    order = sorted(range(n), key=lambda i: vals[i][base[i]], reverse=True)
    rank = [0] * n
    m = [0] * n
    for r, i in enumerate(order):
        rank[i] = r
        m[i] = vals[i][base[i]]

    total_base = sum(m[i] for i in order[:L])

    target = 0
    for i in order[:L]:
        target ^= base[i]

    if target == 0:
        return total_base

    edges = []
    edge_candidates = {}

    for p in range(3):
        for q in range(3):
            if p == q:
                continue

            edge = (p, q)
            edges.append(edge)

            inside = []
            outside = []

            for i in range(n):
                if base[i] != p:
                    continue
                if rank[i] < L:
                    inside.append((vals[i][q] - m[i], i))
                else:
                    outside.append((vals[i][q], i))

            inside.sort(reverse=True)
            outside.sort(reverse=True)

            chosen = {}
            for _, i in inside[:3]:
                chosen[i] = vals[i][q]
            for _, i in outside[:3]:
                chosen[i] = vals[i][q]

            # These near-boundary elements can affect which ordinary top items are removed.
            for pos in range(max(0, L - 2), L):
                i = order[pos]
                if base[i] == p:
                    chosen[i] = vals[i][q]

            edge_candidates[edge] = list(chosen.items())

    def evaluate(specials):
        # specials: list of (index, altered_value), all indices distinct
        s = len(specials)
        special_ids = {i for i, _ in specials}

        inside_count = 0
        removed_inside_sum = 0
        altered_sum = 0

        for i, v in specials:
            altered_sum += v
            if rank[i] < L:
                inside_count += 1
                removed_inside_sum += m[i]

        # Outside special cakes replace the lowest ordinary top-L cakes.
        extra_remove = s - inside_count
        low_removed = 0
        pos = L - 1
        while extra_remove > 0:
            i = order[pos]
            if i not in special_ids:
                low_removed += m[i]
                extra_remove -= 1
            pos -= 1

        return total_base - removed_inside_sum - low_removed + altered_sum

    ans = -1

    # One modified cake.
    for e in edges:
        if (e[0] ^ e[1]) != target:
            continue
        for i, v in edge_candidates[e]:
            ans = max(ans, evaluate([(i, v)]))

    # Two modified cakes.
    for e1 in edges:
        code1 = e1[0] ^ e1[1]
        for e2 in edges:
            if (code1 ^ (e2[0] ^ e2[1])) != target:
                continue

            c1 = edge_candidates[e1]
            c2 = edge_candidates[e2]
            for i, v1 in c1:
                for j, v2 in c2:
                    if i == j:
                        continue
                    ans = max(ans, evaluate([(i, v1), (j, v2)]))

    return ans


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    t = next(it)
    out = []

    for _ in range(t):
        n = next(it)
        k = next(it)
        cakes = []
        for _ in range(n):
            x = next(it)
            y = next(it)
            z = next(it)
            cakes.append((x, y, z))

        out.append(str(solve_case(n, k, cakes)))

    print("\n".join(out))


if __name__ == "__main__":
    main()

