def main():
    input = sys.stdin.readline
    n = int(input())
    s = input().strip()
    t = input().strip()

    mapping = [-1] * 26

    for a, b in zip(s, t):
        x = ord(a) - 97
        y = ord(b) - 97
        if mapping[x] != -1 and mapping[x] != y:
            print(-1)
            return
        mapping[x] = y

    nxt = [-1] * 26
    operations = 0

    for i in range(26):
        if mapping[i] != -1 and mapping[i] != i:
            nxt[i] = mapping[i]
            operations += 1

    state = [0] * 26
    cycles = 0

    for start in range(26):
        if state[start] != 0:
            continue

        path = []
        v = start

        while v != -1 and state[v] == 0:
            state[v] = 1
            path.append(v)
            v = nxt[v]

        if v != -1 and state[v] == 1:
            cycles += 1

        for node in path:
            state[node] = 2

    if cycles > 0 and len(set(t)) == 26:
        print(-1)
    else:
        print(operations + cycles)

