import sys

def shifted(p):
    return p[0] + 1000000, p[1] + 1000000

def solve_case(R, B):
    if R % 2 == 1:
        return ["No"]
    if R == 0 and B % 2 == 1:
        return ["No"]

    ans = ["Yes"]

    def add_piece(color, p):
        r, c = shifted(p)
        ans.append(f"{color} {r} {c}")

    # Only red pieces
    if B == 0:
        if R == 2:
            add_piece("R", (0, 0))
            add_piece("R", (1, 0))
            return ans

        w = R // 2 - 1
        path = []
        for x in range(w + 1):
            path.append((x, 0))
        path.append((w, 1))
        for x in range(w - 1, -1, -1):
            path.append((x, 1))

        for p in path:
            add_piece("R", p)
        return ans

    # Only blue pieces
    if R == 0:
        if B == 2:
            add_piece("B", (0, 0))
            add_piece("B", (1, 1))
            return ans

        w = B // 2 - 1
        abstract = []
        for x in range(w + 1):
            abstract.append((x, 0))
        abstract.append((w, 1))
        for x in range(w - 1, -1, -1):
            abstract.append((x, 1))

        for a, b in abstract:
            add_piece("B", (a + b, a - b))
        return ans

    # Both colors exist. R is positive and even.
    A = (0, 0)

    if B % 2 == 1:
        # Blue path: A -> D, where D = (1, 1)
        k = (B - 1) // 2
        blue = [A]
        for i in range(1, k + 1):
            blue.append((i, -i))
        blue.append((k + 1, -k + 1))
        for j in range(1, k + 1):
            blue.append((k + 1 - j, -k + 1 + j))

        D = (1, 1)

        if R == 2:
            red = [A, (0, 1), D]
        else:
            q = (R - 2) // 2
            red = [A]
            for i in range(1, q + 1):
                red.append((-i, 0))
            red.append((-q, 1))
            for x in range(-q + 1, 2):
                red.append((x, 1))
    else:
        # Blue path: A -> D, where D = (2, 0)
        k = B // 2
        blue = [A]
        for i in range(1, k + 1):
            blue.append((i, -i))
        blue.append((k + 1, -k + 1))
        for j in range(1, k):
            blue.append((k + 1 - j, -k + 1 + j))

        D = (2, 0)

        if R == 2:
            red = [A, (1, 0), D]
        else:
            q = (R - 4) // 2
            red = [A]
            for i in range(1, q + 1):
                red.append((-i, 0))
            red.append((-q, 1))
            for x in range(-q + 1, 3):
                red.append((x, 1))
            red.append(D)

    for p in red[:-1]:
        add_piece("R", p)

    for p in reversed(blue[1:]):
        add_piece("B", p)

    return ans

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    t = data[0]
