import sys
from collections import deque

def main():
    input = sys.stdin.readline
    N, M = map(int, input().split())

    graph = [[] for _ in range(N)]
    for _ in range(M):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        graph[u].append(v)
        graph[v].append(u)

    color = [-1] * N
    odd_components = 0
    parity_value = 0
    has_nontrivial_odd_component = False

    for start in range(N):
        if color[start] != -1:
            continue

        color[start] = 0
        q = deque([start])
        cnt = [1, 0]

        while q:
            v = q.popleft()
            for to in graph[v]:
                if color[to] == -1:
                    color[to] = color[v] ^ 1
                    cnt[color[to]] += 1
                    q.append(to)

        size = cnt[0] + cnt[1]

        if size % 2 == 1:
            odd_components += 1
            if size > 1:
                has_nontrivial_odd_component = True
        else:
            parity_value ^= (cnt[0] & 1)

    if N % 2 == 1:
        print("Aoki" if M % 2 == 1 else "Takahashi")
        return

    if has_nontrivial_odd_component:
        print("Aoki")
        return

    parity_value ^= ((odd_components // 2) & 1)

    if (parity_value ^ (M & 1)) == 1:
        print("Aoki")
    else:
        print("Takahashi")

