    main()

from functools import lru_cache

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_upto(n: int) -> int:
            if n <= 0:
                return 0

            digits = list(map(int, str(n)))
            length = len(digits)
            total = 0

            for target_sum in range(1, 9 * length + 1):
                @lru_cache(None)
                def dp(pos: int, digit_sum: int, product_mod: int, tight: int) -> int:
                    remaining = length - pos

                    if digit_sum > target_sum:
                        return 0
                    if digit_sum + 9 * remaining < target_sum:
                        return 0

                    if pos == length:
                        return 1 if digit_sum == target_sum and product_mod == 0 else 0

                    limit = digits[pos] if tight else 9
                    result = 0

                    for digit in range(limit + 1):
                        new_sum = digit_sum + digit
                        if new_sum > target_sum:
                            break

                        # Leading zeroes do not belong to the number, so they
                        # should not make the product become zero.
                        if digit_sum == 0 and digit == 0:
                            new_mod = product_mod
                        else:
                            new_mod = (product_mod * digit) % target_sum

                        result += dp(
                            pos + 1,
                            new_sum,
                            new_mod,
                            1 if tight and digit == limit else 0
                        )

                    return result

                total += dp(0, 0, 1 % target_sum, 1)

            return total

        return count_upto(r) - count_upto(l - 1)

from typing import List


class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)

        if n - 1 < k:
            return [0] * n

        children = [{}]
        count = [0]
        depth = [0]
        max_depth = 0

        for word in words:
            node = 0
            count[node] += 1

            for ch in word:
                nxt = children[node].get(ch)

                if nxt is None:
                    nxt = len(children)
                    children[node][ch] = nxt
                    children.append({})
                    count.append(0)
                    depth.append(depth[node] + 1)

                node = nxt
                count[node] += 1
                if depth[node] > max_depth:
                    max_depth = depth[node]

        freq = [0] * (max_depth + 1)

        for node in range(len(count)):
            if count[node] >= k:
                freq[depth[node]] += 1

        size = 1
        while size <= max_depth:
            size <<= 1

        seg = [-1] * (2 * size)

        for d in range(max_depth + 1):
            if freq[d] > 0:
                seg[size + d] = d

        for i in range(size - 1, 0, -1):
            seg[i] = max(seg[i * 2], seg[i * 2 + 1])

        def update_depth(d: int) -> None:
            pos = size + d
            value = d if freq[d] > 0 else -1

            if seg[pos] == value:
                return

            seg[pos] = value
            pos //= 2

            while pos:
                new_value = max(seg[pos * 2], seg[pos * 2 + 1])

                if seg[pos] == new_value:
                    break

                seg[pos] = new_value
                pos //= 2

        answer = []

        for word in words:
            affected = []
            node = 0

            for ch in word:
                node = children[node][ch]

                if count[node] == k:
                    d = depth[node]
                    freq[d] -= 1
                    update_depth(d)
                    affected.append(d)

            answer.append(max(0, seg[1]))

            for d in affected:
                freq[d] += 1
                update_depth(d)

        return answer

