import sys
from collections import deque

class Dinic:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        self.g[fr].append([to, cap, len(self.g[to])])
        self.g[to].append([fr, 0, len(self.g[fr]) - 1])

    def max_flow(self, s, t):
        flow = 0
        n = self.n

        while True:
            level = [-1] * n
            level[s] = 0
            q = deque([s])

            while q:
                v = q.popleft()
                for to, cap, rev in self.g[v]:
                    if cap > 0 and level[to] < 0:
                        level[to] = level[v] + 1
                        q.append(to)

            if level[t] < 0:
                return flow

            it = [0] * n

            def dfs(v, f):
                if v == t:
                    return f

                while it[v] < len(self.g[v]):
                    e = self.g[v][it[v]]
                    to, cap, rev = e

                    if cap > 0 and level[v] < level[to]:
                        ret = dfs(to, min(f, cap))
                        if ret:
                            e[1] -= ret
                            self.g[to][rev][1] += ret
                            return ret

                    it[v] += 1

                return 0

            while True:
                pushed = dfs(s, 10**18)
                if pushed == 0:
                    break
                flow += pushed


def main():
    input = sys.stdin.readline
    N, M, K = map(int, input().split())
    edges = [tuple(map(int, input().split())) for _ in range(M)]
    edges = [(u - 1, v - 1) for u, v in edges]

    def feasible(d):
        # x[v][i] = 1 iff the potential of v is at least i
        def node(v, i):
            return (i - 1) * N + v

        source = N * d
        sink = source + 1
        dinic = Dinic(sink + 1)

        INF = K + 1

        for i in range(1, d + 1):
            # Vertex 1 has potential 0, vertex N has potential d.
            dinic.add_edge(node(0, i), sink, INF)
            dinic.add_edge(source, node(N - 1, i), INF)

            # Cost 1 if an edge goes from potential i-1 to i.
            for u, v in edges:
                dinic.add_edge(node(v, i), node(u, i), 1)

        for i in range(1, d):
            for v in range(N):
                # x[v][i+1] => x[v][i]
                dinic.add_edge(node(v, i + 1), node(v, i), INF)

            for u, v in edges:
                # If v has potential at least i+1, u must have at least i.
                dinic.add_edge(node(v, i + 1), node(u, i), INF)

        return dinic.max_flow(source, sink) <= K

    low = 0
    high = N

    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid

    print(low)

if __name__ == "__main__":
    main()

import sys

def main():
    input = sys.stdin.buffer.readline
    N, K = map(int, input().split())
    V = N * K

    graph = [[] for _ in range(V)]
    for _ in range(V - 1):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        graph[u].append(v)
        graph[v].append(u)

    parent = [-1] * V
    order = [0]
    for v in order:
        for to in graph[v]:
            if to != parent[v]:
                parent[to] = v
                order.append(to)

    rem = [0] * V

    for v in reversed(order):
        parts = []
        possible = True

        for to in graph[v]:
            if to == parent[v]:
                continue
            if rem[to] == -1:
                possible = False
                break
            if rem[to] > 0:
                parts.append(rem[to])

        if not possible or len(parts) > 2:
            rem[v] = -1
            continue

        if len(parts) == 2:
            if parts[0] + parts[1] + 1 == K:
                rem[v] = 0
            else:
                rem[v] = -1
        else:
            length = 1 + sum(parts)
            if length == K:
                rem[v] = 0
            elif length < K:
                rem[v] = length
            else:
                rem[v] = -1

    print("Yes" if rem[0] == 0 else "No")

