class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        events = [[] for _ in range(n + 1)]

        for i, (a, b) in enumerate(conflictingPairs):
            left, right = min(a, b), max(a, b)
            events[right].append((left, i))

        max_left = 0
        second_max_left = 0
        max_count = 0
        unique_max_pair = -1

        total = 0
        gain = [0] * len(conflictingPairs)

        for right in range(1, n + 1):
            for left, pair_id in events[right]:
                if left > max_left:
                    second_max_left = max_left
                    max_left = left
                    max_count = 1
                    unique_max_pair = pair_id
                elif left == max_left:
                    max_count += 1
                elif left > second_max_left:
                    second_max_left = left

            total += right - max_left

            if max_count == 1:
                gain[unique_max_pair] += max_left - second_max_left

        return total + max(gain)

