class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        length = n + m - 1

        fixed = [-1] * length

        for i, flag in enumerate(str1):
            if flag == 'T':
                for j, ch in enumerate(str2):
                    pos = i + j
                    val = ord(ch) - 97
                    if fixed[pos] != -1 and fixed[pos] != val:
                        return ""
                    fixed[pos] = val

        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and str2[i] != str2[j]:
                j = pi[j - 1]
            if str2[i] == str2[j]:
                j += 1
            pi[i] = j

        # transition[state][char] = (next_state, completed_pattern)
        transition = [[None] * 26 for _ in range(m)]

        for state in range(m):
            for c in range(26):
                ch = chr(c + 97)
                q = state

                while q > 0 and str2[q] != ch:
                    q = pi[q - 1]

                if str2[q] == ch:
                    q += 1

                completed = 0
                if q == m:
                    completed = 1
                    q = pi[m - 1]

                transition[state][c] = (q, completed)

        # inv[condition][next_state] = bitmask of previous states
        # condition: 0 = no match, 1 = match, 2 = either
        inv = [[0] * m for _ in range(3)]
        inv_char = [[[0] * m for _ in range(3)] for _ in range(26)]

        for state in range(m):
            bit = 1 << state
            for c in range(26):
                nxt, matched = transition[state][c]
                inv[matched][nxt] |= bit
                inv[2][nxt] |= bit
                inv_char[c][matched][nxt] |= bit
                inv_char[c][2][nxt] |= bit

        def preimage(next_mask, inverse_list):
            result = 0
            while next_mask:
                lowbit = next_mask & -next_mask
                state = lowbit.bit_length() - 1
                result |= inverse_list[state]
                next_mask -= lowbit
            return result

        all_states = (1 << m) - 1
        dp = [0] * (length + 1)
        dp[length] = all_states

        for pos in range(length - 1, -1, -1):
            start = pos - m + 1

            if start >= 0:
                required_match = 1 if str1[start] == 'T' else 0
            else:
                required_match = 2

            next_mask = dp[pos + 1]

            if fixed[pos] != -1:
                c = fixed[pos]
                dp[pos] = preimage(next_mask, inv_char[c][required_match])
            else:
                dp[pos] = preimage(next_mask, inv[required_match])

        if (dp[0] & 1) == 0:
            return ""

        result = []
        state = 0

        for pos in range(length):
            start = pos - m + 1
            if start >= 0:
                required_match = 1 if str1[start] == 'T' else 0
            else:
                required_match = 2

            if fixed[pos] != -1:
                candidates = [fixed[pos]]
            else:
                candidates = range(26)

            chosen = -1

            for c in candidates:
                nxt, matched = transition[state][c]

                if required_match != 2 and matched != required_match:
                    continue

                if (dp[pos + 1] >> nxt) & 1:
                    chosen = c
                    state = nxt
                    break

            if chosen == -1:
                return ""

            result.append(chr(chosen + 97))

        return "".join(result)

from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        LIMIT = 10**15

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(LIMIT, fact[i - 1] * i)

        def count_completions(odd_left: int, even_left: int, next_parity: int) -> int:
            total_left = odd_left + even_left
            if total_left == 0:
                return 1

            needed_next = (total_left + 1) // 2
            needed_other = total_left // 2

            if next_parity == 1:
                if odd_left != needed_next or even_left != needed_other:
                    return 0
            else:
                if even_left != needed_next or odd_left != needed_other:
                    return 0

            return min(LIMIT, fact[odd_left] * fact[even_left])

        used = [False] * (n + 1)
        odd_left = (n + 1) // 2
        even_left = n // 2
        result = []
        previous_parity = -1

        for pos in range(n):
            chosen = False

            for x in range(1, n + 1):
                if used[x]:
                    continue

                parity = x % 2
                if previous_parity != -1 and parity == previous_parity:
                    continue

                new_odd = odd_left - (1 if parity == 1 else 0)
                new_even = even_left - (1 if parity == 0 else 0)

                remaining = n - pos - 1
                if remaining == 0:
                    ways = 1
                else:
                    ways = count_completions(new_odd, new_even, 1 - parity)

                if k > ways:
                    k -= ways
                else:
                    result.append(x)
                    used[x] = True
                    odd_left = new_odd
                    even_left = new_even
                    previous_parity = parity
                    chosen = True
                    break

            if not chosen:
                return []

        return result

