def compose(p, r):
    res = 0
    for a in range(2):
        for c in range(2):
            ok = False
            for b in range(2):
                if ((p >> (2 * a + b)) & 1) and ((r >> (2 * b + c)) & 1):
                    ok = True
                    break
            if ok:
                res |= 1 << (2 * a + c)
    return res

