def can_do_in_one(a, b):
    n = len(a)

    pref = [0] * (n + 1)
    for y in range(n):
        expected = (y > 0 and a[y - 1] == '1')
        pref[y + 1] = pref[y] + (expected != (b[y] == '1'))

    suff = [0] * (n + 1)
    for y in range(n - 1, -1, -1):
        expected = (y + 1 < n and a[y + 1] == '1')
        suff[y] = suff[y + 1] + (expected != (b[y] == '1'))

    for p in range(n):
        center = (
            (p > 0 and a[p - 1] == '1') or
            a[p] == '1' or
            (p + 1 < n and a[p + 1] == '1')
        )
        if pref[p] == 0 and suff[p + 1] == 0 and center == (b[p] == '1'):
            return True
    return False

def solve_case(n, a, b):
    pa = [i + 1 for i, c in enumerate(a) if c == '1']
    pb = [i + 1 for i, c in enumerate(b) if c == '1']

    k = len(pa)
    m = len(pb)

    if k < m:
        return -1
    if a == b:
        return 0

    def feasible(d):
        lo = [0] * m
        hi = [0] * m

        lptr = 0
        rptr = 0

        for i, x in enumerate(pb):
            low_value = x - d
            high_value = x + d

            while lptr < k and pa[lptr] < low_value:
                lptr += 1
            while rptr < k and pa[rptr] <= high_value:
                rptr += 1

            lo[i] = lptr
            hi[i] = rptr - 1

            if lo[i] > hi[i]:
                return False

        prev_end = -1

        for i in range(m):
            start = prev_end + 1

            if start < lo[i] or start > hi[i]:
                return False

            if i == m - 1:
                return start <= k - 1 <= hi[i]

            lower = max(start, lo[i + 1] - 1)
            upper = min(hi[i], hi[i + 1] - 1, k - 2)

            if lower > upper:
                return False

            required_gap = pb[i + 1] - pb[i]
            e = lower
            while e <= upper and pa[e + 1] - pa[e] < required_gap:
                e += 1

            if e > upper:
                return False

            prev_end = e

        return False

    low, high = 1, n
    while low < high:
        mid = (low + high) // 2
        if feasible(mid):
            high = mid
        else:
            low = mid + 1

    ans = low

    if ans == 1 and not can_do_in_one(a, b):
        ans = 2

    return ans

