class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        perimeter = 4 * side
        pos = []

        for x, y in points:
            if y == 0:
                pos.append(x)
            elif x == side:
                pos.append(side + y)
            elif y == side:
                pos.append(3 * side - x)
            else:
                pos.append(4 * side - y)

        pos.sort()
        n = len(pos)

        def can(dist: int) -> bool:
            extended = pos + [p + perimeter for p in pos]
            m = 2 * n
            nxt = [m] * m

            j = 0
            for i in range(m):
                if j <= i:
                    j = i + 1
                while j < m and extended[j] - extended[i] < dist:
                    j += 1
                nxt[i] = j

            for start in range(n):
                cur = start

                for _ in range(k - 1):
                    cur = nxt[cur]
                    if cur >= start + n:
                        break

                if cur < start + n and extended[start] + perimeter - extended[cur] >= dist:
                    return True

            return False

        low, high = 0, side + 1

        while low + 1 < high:
            mid = (low + high) // 2
            if can(mid):
                low = mid
            else:
                high = mid

        return low

