import heapq

def solve():
    input = sys.stdin.readline
    N = int(input())
    C = [input().strip() for _ in range(N)]

    incoming = [[] for _ in range(N)]
    outmask = [[0] * 26 for _ in range(N)]

    dist = [[-1] * N for _ in range(N)]
    unvisited = [(1 << N) - 1 for _ in range(N)]
    heap = []

    for i in range(N):
        dist[i][i] = 0
        unvisited[i] &= ~(1 << i)
        heap.append((0, i, i))

    for i in range(N):
        row = C[i]
        for j, ch in enumerate(row):
            if ch == '-':
                continue
            c = ord(ch) - 97
            outmask[i][c] |= 1 << j

            # Store incoming edges grouped by destination and character.
            # Temporarily use a dictionary-like list construction below.
            if dist[i][j] == -1:
                dist[i][j] = 1
                unvisited[i] &= ~(1 << j)
                heap.append((1, i, j))

    grouped_incoming = [[[] for _ in range(26)] for _ in range(N)]
    for i in range(N):
        for j, ch in enumerate(C[i]):
            if ch != '-':
                grouped_incoming[j][ord(ch) - 97].append(i)

    for v in range(N):
        for c in range(26):
            if grouped_incoming[v][c]:
                incoming[v].append((c, grouped_incoming[v][c]))

    heapq.heapify(heap)

    while heap:
        d, u, v = heapq.heappop(heap)
        nd = d + 2

        for c, predecessors in incoming[u]:
            targets = outmask[v][c]
            if targets == 0:
                continue

            for a in predecessors:
                candidates = unvisited[a] & targets
                while candidates:
                    bit = candidates & -candidates
                    b = bit.bit_length() - 1

                    unvisited[a] ^= bit
                    dist[a][b] = nd
                    heapq.heappush(heap, (nd, a, b))

                    candidates ^= bit

    print('\n'.join(' '.join(map(str, row)) for row in dist))

