class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        total = n * m
        values = [x for row in grid for x in row]

        # Directions in clockwise order:
        # SE -> SW -> NW -> NE -> SE
        directions = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        # tails[d][idx] = longest alternating 2,0,2,0,... sequence
        # beginning at idx and moving in direction d, assuming the value
        # at idx is the first required value.
        tails = []

        for dr, dc in directions:
            tail = array('H', [0]) * total

            row_range = range(n - 1, -1, -1) if dr == 1 else range(n)
            col_range = range(m - 1, -1, -1) if dc == 1 else range(m)

            for r in row_range:
                base = r * m
                for c in col_range:
                    idx = base + c
                    cur = values[idx]

                    if cur != 0 and cur != 2:
                        continue

                    length = 1
                    nr, nc = r + dr, c + dc

                    if 0 <= nr < n and 0 <= nc < m:
                        nxt_idx = nr * m + nc
                        nxt = values[nxt_idx]

                        if (cur == 2 and nxt == 0) or (cur == 0 and nxt == 2):
                            length += tail[nxt_idx]

                    tail[idx] = length

            tails.append(tail)

        answer = 0

        # straight[d][idx] = longest valid segment starting from a 1
        # and ending at idx while moving in direction d.
        for d, (dr, dc) in enumerate(directions):
            straight = array('H', [0]) * total
            turn_dir = (d + 1) % 4

            row_range = range(n) if dr == 1 else range(n - 1, -1, -1)
            col_range = range(m) if dc == 1 else range(m - 1, -1, -1)

            for r in row_range:
                base = r * m
                for c in col_range:
                    idx = base + c
                    cur = values[idx]

                    if cur == 1:
                        straight[idx] = 1
                    else:
                        pr, pc = r - dr, c - dc

                        if 0 <= pr < n and 0 <= pc < m:
                            prev_idx = pr * m + pc
                            prev = values[prev_idx]

                            if cur == 2:
                                if (prev == 1 or prev == 0) and straight[prev_idx] > 0:
                                    straight[idx] = straight[prev_idx]
                            elif cur == 0:
                                if prev == 2 and straight[prev_idx] > 0:
                                    straight[idx] = straight[prev_idx]

                    current_length = straight[idx]
                    if current_length == 0:
                        continue

                    if current_length > answer:
                        answer = current_length

                    # Try making one clockwise turn after this cell.
                    tr, tc = directions[turn_dir]
                    nr, nc = r + tr, c + tc

                    if 0 <= nr < n and 0 <= nc < m:
                        next_idx = nr * m + nc
                        needed = 0 if cur == 2 else 2

                        if values[next_idx] == needed:
                            candidate = current_length + tails[turn_dir][next_idx]
                            if candidate > answer:
                                answer = candidate

        return answer

from bisect import bisect_left


class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def find_occurrences(pattern: str):
            if not pattern:
                return list(range(n + 1))

            m = len(pattern)
            lps = [0] * m
            j = 0

            for i in range(1, m):
                while j > 0 and pattern[i] != pattern[j]:
                    j = lps[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                    lps[i] = j

            occurrences = []
            j = 0
            for i, ch in enumerate(s):
                while j > 0 and ch != pattern[j]:
                    j = lps[j - 1]
                if ch == pattern[j]:
                    j += 1
                if j == m:
                    occurrences.append(i - m + 1)
                    j = lps[j - 1]

            return occurrences

        occ_a = find_occurrences(a)
        occ_b = find_occurrences(b)
        occ_c = find_occurrences(c)

        len_a = len(a)
        len_b = len(b)
        len_c = len(c)

        answer = float("inf")

        for start_a in occ_a:
            idx_b = bisect_left(occ_b, start_a + len_a)
            if idx_b == len(occ_b):
                continue

            start_b = occ_b[idx_b]
            idx_c = bisect_left(occ_c, start_b + len_b)
            if idx_c == len(occ_c):
                continue

            end_c = occ_c[idx_c] + len_c
            answer = min(answer, end_c - start_a)

        return -1 if answer == float("inf") else answer

