class Solution:
    def countSubstrings(self, s: str) -> int:
        states = [[0] * d for d in range(10)]
        ans = 0

        for ch in s:
            digit = ord(ch) - ord('0')

            for d in range(1, 10):
                old = states[d]
                new = [0] * d

                for remainder, count in enumerate(old):
                    if count:
                        new[(remainder * 10 + digit) % d] += count

                new[digit % d] += 1
                states[d] = new

            if digit != 0:
                ans += states[digit][0]

        return ans

