class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def can(target: int) -> bool:
            if target == 0:
                return True

            moves = 1  # first move: -1 -> 0
            visits_here = 1

            for i in range(n - 1):
                need = (target + points[i] - 1) // points[i]

                extra = max(0, need - visits_here)
                moves += 2 * extra + 1

                if moves > m:
                    return False

                visits_here = extra + 1

            need_last = (target + points[-1] - 1) // points[-1]
            extra_last = max(0, need_last - visits_here)
            moves += 2 * extra_last

            return moves <= m

        lo, hi = 0, max(points) * m

        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo

