        for i in range(N):
            old[i + 1] = old[i] + ((mask >> i) & 1)

        for c in range(26):
            new = [0] * (N + 1)
            for i in range(1, N + 1):
                v = old[i]
                if new[i - 1] > v:
                    v = new[i - 1]
                if ord(S[i - 1]) - 97 == c and old[i - 1] + 1 > v:
                    v = old[i - 1] + 1
                new[i] = v

            nm = 0
            for i in range(N):
                if new[i + 1] > new[i]:
                    nm |= 1 << i
            nxt[mask][c] = nm

    dp = [0] * size
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * size
        for mask, value in enumerate(dp):
            if value == 0:
                continue
            for c in range(26):
                to = nxt[mask][c]
                ndp[to] += value
                if ndp[to] >= MOD:
                    ndp[to] -= MOD
        dp = ndp

    ans = [0] * (N + 1)
    for mask, value in enumerate(dp):
        ans[mask.bit_count()] += value
        if ans[mask.bit_count()] >= MOD:
            ans[mask.bit_count()] -= MOD

    print(*ans)

