import math

def main():
    N, P = map(int, sys.stdin.readline().split())
    H = N // 2
    EMAX = N * (N - 1) // 2

    comb = [[0] * (N + 1) for _ in range(N + 1)]
    for n in range(N + 1):
        comb[n][0] = comb[n][n] = 1
        for k in range(1, n):
            comb[n][k] = comb[n - 1][k - 1] + comb[n - 1][k]

    # transition[a][b]:
    # y^(C(b,2)) * (y^a - 1)^b
    # represented as (shift, coefficient) pairs in y-basis.
    transition = [[None] * (H + 1) for _ in range(H + 1)]
    for a in range(1, H + 1):
        for b in range(1, H + 1):
            base = b * (b - 1) // 2
            arr = []
            for k in range(b + 1):
                c = comb[b][k]
                if (b - k) & 1:
                    c = -c
                arr.append((base + a * k, c))
            transition[a][b] = arr

    # dp[s][(even_count, last_layer_size, last_layer_parity)] = polynomial in y
    # parity: 0 = even-distance layer, 1 = odd-distance layer
    dp = [dict() for _ in range(N + 1)]
    dp[1][(1, 1, 0)] = [1]

    for s in range(1, N):
        cur = dp[s]
        if not cur:
            continue

        remaining_total = N - s

        for (even_cnt, a, parity), poly_raw in cur.items():
            poly = [v % P for v in poly_raw]

            odd_cnt = s - even_cnt
            next_parity = parity ^ 1

            if next_parity == 0:
                max_b = H - even_cnt
            else:
                max_b = H - odd_cnt

            if max_b <= 0:
                continue

            max_b = min(max_b, remaining_total)

            for b in range(1, max_b + 1):
                ns = s + b
                ne = even_cnt + (b if next_parity == 0 else 0)

                label_ways = comb[N - s][b]
                key = (ne, b, next_parity)

                target_dict = dp[ns]
                dest = target_dict.get(key)

                terms = transition[a][b]
                max_shift = terms[-1][0]
                needed = len(poly) + max_shift

                if dest is None:
                    dest = [0] * needed
                    target_dict[key] = dest
                elif len(dest) < needed:
                    dest.extend([0] * (needed - len(dest)))

                for shift, coef in terms:
                    mul = (label_ways * coef) % P
                    if mul == 0:
                        continue
                    end = shift + len(poly)
                    for i in range(len(poly)):
                        dest[shift + i] += poly[i] * mul

        dp[s].clear()

    ypoly = [0] * (EMAX + 1)
    for (even_cnt, a, parity), poly in dp[N].items():
        if even_cnt != H:
            continue
        for i, v in enumerate(poly):
            ypoly[i] = (ypoly[i] + v) % P

    # Convert polynomial in y = 1 + x basis to polynomial in x basis.
    ans = [0] * (EMAX + 1)
    for q, coef in enumerate(ypoly):
        if coef == 0:
            continue
        for m in range(q + 1):
            ans[m] = (ans[m] + coef * comb[q][m]) % P

    print(" ".join(map(str, ans[N - 1:])))

if __name__ == "__main__":
    main()

import sys

def main():
    input = sys.stdin.readline
    N, M = map(int, input().split())
    P = sorted(map(int, input().split()))

    def feasible(x):
        total = 0
        for p in P:
            if p > x:
                break
            k = (x // p + 1) // 2
            total += k * k * p
            if total > M:
                return False
        return True

    lo, hi = 0, M
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1

    x = lo
    total_cost = 0
    total_units = 0

    for p in P:
        if p > x:
            break
        k = (x // p + 1) // 2
        total_units += k
        total_cost += k * k * p

    remaining = M - total_cost
    total_units += remaining // (x + 1)

    print(total_units)

