import sys

def mat_mul(A, B, mod):
    n = len(A)
    BT = list(zip(*B))
    return [
        [sum(x * y for x, y in zip(row, col)) % mod for col in BT]
        for row in A
    ]

def mat_pow(A, e, mod):
    n = len(A)
    R = [[0] * n for _ in range(n)]
    for i in range(n):
        R[i][i] = 1

    while e > 0:
        if e & 1:
            R = mat_mul(R, A, mod)
        e >>= 1
        if e:
            A = mat_mul(A, A, mod)
    return R

def main():
    input = sys.stdin.readline
    N, p = map(int, input().split())
    A = [list(map(int, input().split())) for _ in range(N)]

    if p == 2:
        B = [[1 if A[i][j] == 0 else A[i][j] for j in range(N)] for i in range(N)]
        ans = mat_mul(B, B, p)
        for row in ans:
            print(*row)
        return

    K = sum(A[i][j] == 0 for i in range(N) for j in range(N))

    C = [[A[i][j] if A[i][j] != 0 else 0 for j in range(N)] for i in range(N)]
    ans = mat_pow(C, p, p)

    # Contributions where the repeated zero entry is a diagonal entry.
    for a in range(N):
        if A[a][a] == 0:
            for j in range(N):
                ans[a][j] = (ans[a][j] + C[a][j]) % p
            for i in range(N):
                ans[i][a] = (ans[i][a] + C[i][a]) % p

    # For p = 3, an off-diagonal zero may appear twice,
    # with one fixed edge between the two occurrences.
    if p == 3:
        for a in range(N):
            for b in range(N):
                if a != b and A[a][b] == 0:
                    ans[a][b] = (ans[a][b] + C[b][a]) % p

    if K % 2 == 1:
        for i in range(N):
            for j in range(N):
                ans[i][j] = (-ans[i][j]) % p

    for row in ans:
        print(*row)

if __name__ == "__main__":
    main()

import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, M, A, B = data[:4]
    intervals = []
    idx = 4
    for _ in range(M):
        L, R = data[idx], data[idx + 1]
        idx += 2
        intervals.append((L, R))

    if A == B:
        if (N - 1) % A != 0:
            print("No")
            return

        for L, R in intervals:
            first = L + ((1 - L) % A)
            if first <= R:
                print("No")
                return

        print("Yes")
        return

    width = B - A + 1
    predecessor_mask = ((1 << width) - 1) << (A - 1)
    history_mask = (1 << B) - 1

    # After a reachable point, every position at distance at least A*(A-1)
    # is reachable using steps A and A+1.
    prefix_length = A * (A - 1) + 2 * B

    mask = 0
    last_processed = 0

    def process_segment(left, right):
        nonlocal mask, last_processed

        gap = left - last_processed - 1
        if gap >= B:
            mask = 0
        elif gap > 0:
            mask = (mask << gap) & history_mask

        end_prefix = min(right, left + prefix_length - 1)

        for x in range(left, end_prefix + 1):
            if x == 1:
                reachable = 1
            else:
                reachable = 1 if (mask & predecessor_mask) else 0
            mask = ((mask << 1) & history_mask) | reachable

        last_processed = end_prefix

        if end_prefix < right:
            if mask:
                mask = history_mask
            else:
                mask = 0
            last_processed = right

    current = 1
    for L, R in intervals:
        if current <= L - 1:
            process_segment(current, L - 1)
        current = R + 1

    if current <= N:
        process_segment(current, N)

    print("Yes" if (mask & 1) else "No")


if __name__ == "__main__":
    main()

from typing import List


class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        NEG_INF = -10**30
        EMPTY = (0, NEG_INF, NEG_INF, NEG_INF)

        def combine(a, b):
            total = a[0] + b[0]
            pref = max(a[1], a[0] + b[1])
            suff = max(b[2], b[0] + a[2])
            best = max(a[3], b[3], a[2] + b[1])
            return (total, pref, suff, best)

        def build(left: int, right: int):
            if right - left == 1:
                value = nums[left]
                base = (value, value, value, value)
                if value < 0:
                    return base, {value: EMPTY}
                return base, {}

            mid = (left + right) // 2
            base_left, removed_left = build(left, mid)
            base_right, removed_right = build(mid, right)

            base = combine(base_left, base_right)
            removed = {}

            for value, state_left in removed_left.items():
                state_right = removed_right.get(value, base_right)
                removed[value] = combine(state_left, state_right)

            for value, state_right in removed_right.items():
                if value not in removed_left:
                    removed[value] = combine(base_left, state_right)

            return base, removed

        base, removed = build(0, len(nums))
        answer = base[3]

        for state in removed.values():
            answer = max(answer, state[3])

        return answer

import sys
from collections import deque
from array import array

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N, M = data[0], data[1]
    A = [x - 1 for x in data[2:]]

    indeg = [0] * N
    for v in A:
        indeg[v] += 1

    q = deque()
    for i in range(N):
        if indeg[i] == 0:
            q.append(i)

    while q:
        v = q.popleft()
        to = A[v]
        indeg[to] -= 1
        if indeg[to] == 0:
            q.append(to)

    is_cycle = [indeg[i] > 0 for i in range(N)]

    rep = [-1] * N
    seen = [False] * N
    roots = []

    for i in range(N):
        if is_cycle[i] and not seen[i]:
            roots.append(i)
            v = i
            while not seen[v]:
                seen[v] = True
                rep[v] = i
                v = A[v]

    active = [False] * N
    for i in range(N):
        if not is_cycle[i]:
            active[i] = True
    for r in roots:
        active[r] = True

    parent = [-1] * N
    child_count = [0] * N

    for i in range(N):
        if not is_cycle[i]:
            p = A[i]
            if is_cycle[p]:
                p = rep[p]
            parent[i] = p
            child_count[p] += 1

    queue = deque()
    for i in range(N):
        if active[i] and child_count[i] == 0:
            queue.append(i)

    aggregates = [None] * N
    answer = 1

    while queue:
        v = queue.popleft()
        agg = aggregates[v]
        p = parent[v]

        if p == -1:
            if agg is None:
                ways = M % MOD
            else:
                ways = sum(agg) % MOD
            answer = (answer * ways) % MOD
            continue

        if aggregates[p] is None:
            aggregates[p] = array('I', [1]) * M

        target = aggregates[p]

        if agg is None:
            for j in range(M):
                target[j] = (target[j] * (j + 1)) % MOD
        else:
            pref = 0
            for j in range(M):
                pref += agg[j]
                if pref >= MOD:
                    pref -= MOD
                target[j] = (target[j] * pref) % MOD

        aggregates[v] = None
        child_count[p] -= 1
        if child_count[p] == 0:
            queue.append(p)

    print(answer)

if __name__ == "__main__":
    main()

